import { AggregatorError } from "../port.ts";
import type { CarrierEvent } from "../../domain/types.ts";

/**
 * Único lugar que conhece o formato do payload do TrackHub (agregador fictício):
 * { tracking_number, courier, checkpoints: [{ id, status_code, message, time, city }] }.
 * Devolve eventos no formato interno; o código da transportadora (`status_code`) segue bruto.
 */
const invalid = (why: string) => new AggregatorError("invalid_payload", `payload do TrackHub inválido: ${why}`);

/**
 * O envelope tem que ser do envio pedido: sem isso, a resposta de outro código ou de outra transportadora seria
 * lida com o dialeto do envio consultado (um "40" de uma transportadora qualquer viraria entrega).
 */
export function verifyTrackHubEnvelope(payload: unknown, expected: { code: string; carrier: string }): void {
  if (typeof payload !== "object" || payload === null) throw invalid("o corpo não é um objeto");
  const { tracking_number: trackingNumber, courier } = payload as { tracking_number?: unknown; courier?: unknown };
  if (typeof trackingNumber !== "string" || trackingNumber.trim().toUpperCase() !== expected.code.trim().toUpperCase()) {
    throw invalid("tracking_number ausente ou de outro envio");
  }
  if (typeof courier !== "string" || courier.trim().toLowerCase() !== expected.carrier) {
    throw invalid("courier ausente ou de outra transportadora");
  }
}

export function mapTrackHubPayload(payload: unknown): CarrierEvent[] {
  if (typeof payload !== "object" || payload === null) throw invalid("o corpo não é um objeto");
  const checkpoints = (payload as { checkpoints?: unknown }).checkpoints;
  if (!Array.isArray(checkpoints)) throw invalid("checkpoints ausente ou não é uma lista");

  return checkpoints.map((raw, index): CarrierEvent => {
    const checkpoint = (typeof raw === "object" && raw !== null ? raw : {}) as Record<string, unknown>;
    const code = checkpoint.status_code;
    if (typeof code !== "string" || code.trim() === "") throw invalid(`checkpoint ${index} sem status_code`);
    const time = typeof checkpoint.time === "string" ? Date.parse(checkpoint.time) : Number.NaN;
    if (Number.isNaN(time)) throw invalid(`checkpoint ${index} com data inválida`);
    return {
      rawStatus: code,
      description: typeof checkpoint.message === "string" ? checkpoint.message : null,
      occurredAt: new Date(time).toISOString(),
      location: typeof checkpoint.city === "string" ? checkpoint.city : null,
    };
  });
}

src/domain/delay.ts.source:
import type { Status } from "./types.ts";

/**
 * Atraso: o envio NÃO foi entregue e já passou mais que o limite desde o primeiro evento (a postagem),
 * ou desde o cadastro se ainda não há evento. "Mais que" é estrito: no limite exato ainda está no prazo.
 *
 * Entregue nunca é atraso, mesmo que a consulta aconteça semanas depois (a comparação de uma entrega
 * normal com "agora" é justamente o erro que marcaria entrega normal como atraso). Entrega que levou mais
 * que o limite fica só informada em `deliveredLate`, sem alerta.
 */
const HOUR_MS = 3_600_000;

export type DelayInput = {
  status: Status | null;
  startedAt: string;
  deliveredAt: string | null;
  now: Date;
  thresholdHours: number;
};

export type DelayAssessment = {
  delayed: boolean;
  elapsedHours: number;
  thresholdHours: number;
  startedAt: string;
  deliveredLate: boolean | null;
};

export function assessDelay(input: DelayInput): DelayAssessment {
  const started = Date.parse(input.startedAt);
  const thresholdMs = input.thresholdHours * HOUR_MS;
  const elapsedMs = Math.max(0, input.now.getTime() - started);
  const isDelivered = input.status === "delivered";
  const deliveredLate =
    isDelivered && input.deliveredAt !== null ? Date.parse(input.deliveredAt) - started > thresholdMs : null;
  return {
    delayed: !isDelivered && elapsedMs > thresholdMs,
    elapsedHours: elapsedMs / HOUR_MS,
    thresholdHours: input.thresholdHours,
    startedAt: input.startedAt,
    deliveredLate: isDelivered ? deliveredLate : null,
  };
}

src/domain/dialects.ts.source:
import type { Status } from "./types.ts";

/**
 * Dialeto de cada transportadora: código bruto (em maiúsculas, sem espaços) → status normalizado.
 * Transportadora nova é uma entrada nova aqui; ninguém mais precisa saber como ela fala.
 */
const DIALECTS: Record<string, Record<string, Status>> = {
  "via-rapida": {
    "10": "posted",
    "20": "in_transit",
    "21": "in_transit",
    "30": "out_for_delivery",
    "40": "delivered",
    "90": "exception", // tentativa de entrega falhou
    "91": "exception", // devolvido ao remetente
  },
  "correio-norte": {
    OBJETO_POSTADO: "posted",
    EM_TRANSITO: "in_transit",
    SAIU_PARA_ENTREGA: "out_for_delivery",
    ENTREGUE: "delivered",
    TENTATIVA_FALHA: "exception",
    DEVOLVIDO: "exception",
  },
};

export const SUPPORTED_CARRIERS = Object.keys(DIALECTS).sort();

export function lookupStatus(carrier: string, rawStatus: string): Status | "unknown_carrier" | undefined {
  const table = Object.hasOwn(DIALECTS, carrier) ? DIALECTS[carrier] : undefined;
  if (!table) return "unknown_carrier";
  const key = rawStatus.trim().toUpperCase();
  return Object.hasOwn(table, key) ? table[key] : undefined;
}

src/domain/normalize.ts.source:
import { lookupStatus } from "./dialects.ts";
import type { CarrierEvent, NormalizedEvent } from "./types.ts";

/**
 * Traduz um evento do dialeto da transportadora para o status normalizado.
 * O que não está no dialeto NUNCA vira entregue: vira exceção, com o motivo e o bruto preservados,
 * para alguém olhar (e para o mapeamento ser completado).
 */
export function normalizeEvent(carrier: string, event: CarrierEvent): NormalizedEvent {
  const occurredAt = new Date(event.occurredAt).toISOString();
  const found = lookupStatus(carrier, event.rawStatus);
  const base = {
    ...event,
    occurredAt,
    carrier,
    dedupeKey: `${carrier}|${event.rawStatus.trim().toUpperCase()}|${occurredAt}`,
  };
  if (found === "unknown_carrier") return { ...base, status: "exception", reason: "unknown_carrier" };
  if (found === undefined) return { ...base, status: "exception", reason: "unmapped_carrier_status" };
  return { ...base, status: found, reason: null };
}

src/domain/status.ts.source:
import type { NormalizedEvent, Status } from "./types.ts";

/**
 * Status atual de um envio, calculado SEMPRE a partir do histórico inteiro (nada é atualizado "aos poucos"),
 * então a ordem em que os eventos chegaram não muda o resultado.
 *
 * - Vale o evento de maior data de ocorrência (não o de chegada): evento antigo que chega depois não regride nada.
 * - Empate de horário: entregue > exceção > saiu para entrega > em trânsito > postado.
 * - Empate também no status (duas exceções no mesmo instante): vence o evento com motivo, ou seja, o código que a
 *   transportadora inventou (a anomalia continua visível para completar o mapeamento), e por fim a dedupeKey.
 *   A ordem é total, então o resultado nunca depende da ordem de chegada.
 * - Entregue é terminal: eventos posteriores à entrega ficam no histórico, marcados, sem mudar o status.
 * - Exceção seguida de um evento mais novo se recupera (a tentativa falha de hoje vira a entrega de amanhã).
 */
const TIE_PRIORITY: Record<Status, number> = {
  posted: 0,
  in_transit: 1,
  out_for_delivery: 2,
  exception: 3,
  delivered: 4,
};

export type Fold = {
  status: Status | null;
  reason: string | null;
  startedAt: string | null;
  lastEventAt: string | null;
  deliveredAt: string | null;
  /** dedupeKey dos eventos posteriores à entrega. */
  afterDelivered: Set<string>;
};

const at = (event: NormalizedEvent) => Date.parse(event.occurredAt);

/** Ordem total e crescente: o último elemento é o que vale. */
function byTimeThenPriority(a: NormalizedEvent, b: NormalizedEvent): number {
  return (
    at(a) - at(b) ||
    TIE_PRIORITY[a.status] - TIE_PRIORITY[b.status] ||
    Number(a.reason !== null) - Number(b.reason !== null) ||
    (a.dedupeKey < b.dedupeKey ? -1 : a.dedupeKey > b.dedupeKey ? 1 : 0)
  );
}

export function foldEvents(events: NormalizedEvent[]): Fold {
  if (events.length === 0) {
    return { status: null, reason: "no_events_yet", startedAt: null, lastEventAt: null, deliveredAt: null, afterDelivered: new Set() };
  }
  const ordered = [...events].sort(byTimeThenPriority);
  const first = ordered[0] as NormalizedEvent;
  const last = ordered[ordered.length - 1] as NormalizedEvent;
  const delivered = ordered.find((event) => event.status === "delivered");

  if (delivered) {
    const after = ordered.filter((event) => at(event) > at(delivered) && event.status !== "delivered");
    return {
      status: "delivered",
      reason: delivered.reason,
      startedAt: first.occurredAt,
      lastEventAt: last.occurredAt,
      deliveredAt: delivered.occurredAt,
      afterDelivered: new Set(after.map((event) => event.dedupeKey)),
    };
  }
  return {
    status: last.status,
    reason: last.reason,
    startedAt: first.occurredAt,
    lastEventAt: last.occurredAt,
    deliveredAt: null,
    afterDelivered: new Set(),
  };
}

src/store.ts.source:
import type { DatabaseSync } from "node:sqlite";
import { inTransaction } from "./db.ts";
import { normalizeEvent } from "./domain/normalize.ts";
import { foldEvents } from "./domain/status.ts";
import type { CarrierEvent, NormalizedEvent, Status } from "./domain/types.ts";

type ShipmentRow = {
  tracking_code: string;
  carrier: string;
  creator_id: string | null;
  campaign_id: string | null;
  registered_at: string;
  status: Status | null;
  started_at: string | null;
  delivered_at: string | null;
};

type EventRow = {
  dedupe_key: string;
  raw_status: string;
  status: Status;
  reason: string | null;
  description: string | null;
  location: string | null;
  occurred_at: string;
};

export function normalizeCode(code: string): string {
  return code.trim().toUpperCase();
}

export function findShipment(db: DatabaseSync, code: string): ShipmentRow | undefined {
  return db.prepare("SELECT * FROM shipments WHERE tracking_code = ?").get(code) as ShipmentRow | undefined;
}

export function registerShipment(
  db: DatabaseSync,
  shipment: { code: string; carrier: string; creatorId: string | null; campaignId: string | null },
  now: () => Date,
): "created" | "exists" | "conflict" {
  return inTransaction(db, () => {
    const inserted = db
      .prepare(
        `INSERT INTO shipments (tracking_code, carrier, creator_id, campaign_id, registered_at)
         VALUES (?, ?, ?, ?, ?) ON CONFLICT(tracking_code) DO NOTHING`,
      )
      .run(shipment.code, shipment.carrier, shipment.creatorId, shipment.campaignId, now().toISOString());
    if (inserted.changes === 1) return "created" as const;
    return findShipment(db, shipment.code)?.carrier === shipment.carrier ? ("exists" as const) : ("conflict" as const);
  });
}

function storedEvents(db: DatabaseSync, code: string, carrier: string): NormalizedEvent[] {
  const rows = db.prepare("SELECT * FROM tracking_events WHERE tracking_code = ?").all(code) as EventRow[];
  return rows.map((row) => ({
    carrier,
    rawStatus: row.raw_status,
    description: row.description,
    location: row.location,
    occurredAt: row.occurred_at,
    status: row.status,
    reason: row.reason,
    dedupeKey: row.dedupe_key,
  }));
}

/**
 * Grava os eventos novos (os já conhecidos são ignorados) e recalcula o status a partir do histórico inteiro,
 * tudo na mesma transação. Devolve null se o envio não foi cadastrado.
 */
export function ingestEvents(db: DatabaseSync, code: string, events: CarrierEvent[], now: () => Date) {
  return inTransaction(db, () => {
    const shipment = findShipment(db, code);
    if (!shipment) return null;

    const insert = db.prepare(
      `INSERT INTO tracking_events (tracking_code, dedupe_key, raw_status, status, reason, description, location, occurred_at, received_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT(tracking_code, dedupe_key) DO NOTHING`,
    );
    let added = 0;
    let duplicates = 0;
    for (const event of events) {
      const n = normalizeEvent(shipment.carrier, event);
      const result = insert.run(code, n.dedupeKey, n.rawStatus, n.status, n.reason, n.description, n.location, n.occurredAt, now().toISOString());
      if (result.changes === 1) added += 1;
      else duplicates += 1;
    }

    const fold = foldEvents(storedEvents(db, code, shipment.carrier));
    db.prepare("UPDATE shipments SET status = ?, reason = ?, started_at = ?, delivered_at = ? WHERE tracking_code = ?").run(
      fold.status,
      fold.reason,
      fold.startedAt,
      fold.deliveredAt,
      code,
    );
    return { added, duplicates, status: fold.status, reason: fold.reason };
  });
}

export function loadShipment(db: DatabaseSync, code: string) {
  const shipment = findShipment(db, code);
  if (!shipment) return null;
  const events = storedEvents(db, code, shipment.carrier);
  const fold = foldEvents(events);
  const history = [...events]
    .sort((a, b) => Date.parse(a.occurredAt) - Date.parse(b.occurredAt) || a.dedupeKey.localeCompare(b.dedupeKey))
    .map((event) => ({
      status: event.status,
      raw_status: event.rawStatus,
      description: event.description,
      location: event.location,
      occurred_at: event.occurredAt,
      reason: event.reason,
      ignored: fold.afterDelivered.has(event.dedupeKey) ? ("after_delivered" as const) : null,
    }));
  return {
    tracking_code: shipment.tracking_code,
    carrier: shipment.carrier,
    creator_id: shipment.creator_id,
    campaign_id: shipment.campaign_id,
    registered_at: shipment.registered_at,
    status: fold.status,
    reason: fold.reason,
    started_at: fold.startedAt,
    delivered_at: fold.deliveredAt,
    history,
  };
}

/** Envios ainda não entregues, que são os candidatos a atraso. */
export function listOpenShipments(db: DatabaseSync): ShipmentRow[] {
  return db.prepare("SELECT * FROM shipments WHERE status IS NOT 'delivered'").all() as ShipmentRow[];
}

