import { serve } from "@hono/node-server";
import type { AddressInfo } from "node:net";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { createApp } from "../src/app.ts";
import { HttpTrackHubClient } from "../src/aggregator/trackhub/client.ts";
import type { TrackingAggregator } from "../src/aggregator/port.ts";
import { openDatabase } from "../src/db.ts";
import { InMemoryAggregator, RecordingNotifier } from "./fakes.ts";
import { startFakeTrackHub, type RawTracking } from "./fake-trackhub.ts";
import { DELIVERED, IN_TRANSIT, POSTED, H, T0, viaRapida } from "./fixtures.ts";

let hub: Awaited<ReturnType<typeof startFakeTrackHub>>;
let server: ReturnType<typeof serve>;
let base = "";
const notifier = new RecordingNotifier();
const clock = { current: T0 };

function build(aggregator: TrackingAggregator) {
  return createApp({ db: openDatabase(":memory:"), aggregator, notifier, now: () => new Date(clock.current), thresholdHours: 72 });
}

beforeAll(async () => {
  hub = await startFakeTrackHub();
  const aggregator = new HttpTrackHubClient({ baseUrl: hub.baseUrl, apiKey: hub.apiKey, timeoutMs: 1000 });
  server = serve({ fetch: build(aggregator).fetch, port: 0, hostname: "127.0.0.1" });
  await new Promise<void>((resolve) => server.once("listening", () => resolve()));
  base = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
});
afterAll(async () => {
  server.close();
  await hub.close();
});

const send = (method: string, path: string, body?: unknown) =>
  fetch(base + path, { method, headers: { "content-type": "application/json" }, body: body ? JSON.stringify(body) : undefined });

describe("jornada completa por HTTP, com o cliente real do TrackHub", () => {
  it("cadastra, consulta duas vezes, vê a entrega chegar e o atraso não disparar", async () => {
    const raw: RawTracking = {
      tracking_number: "BR777",
      courier: "correio-norte",
      checkpoints: [
        { id: "1", status_code: "OBJETO_POSTADO", message: "Postado", time: "2026-06-01T10:00:00Z", city: "Natal" },
        { id: "2", status_code: "EM_TRANSITO", message: "A caminho", time: "2026-06-02T10:00:00Z", city: null },
      ],
    };
    hub.state.trackings.set("BR777", raw);

    const created = await send("POST", "/shipments", { tracking_code: "BR777", carrier: "correio-norte", creator_id: "crt_ana" });
    expect(created.status).toBe(201);
    expect(hub.state.registered.get("BR777")).toBe("correio-norte");

    await send("POST", "/shipments/BR777/refresh");
    const second = await (await send("POST", "/shipments/BR777/refresh")).json();
    expect(second).toMatchObject({ added: 0, duplicates: 2, status: "in_transit" });

    raw.checkpoints.push({ id: "3", status_code: "ENTREGUE", message: "Entregue ao destinatário", time: "2026-06-03T10:00:00Z", city: "Natal" });
    await send("POST", "/shipments/BR777/refresh");

    clock.current = T0 + 400 * H;
    const shipment = await (await send("GET", "/shipments/BR777")).json();
    expect(shipment).toMatchObject({ status: "delivered", delivered_at: "2026-06-03T10:00:00.000Z" });
    expect(shipment.delay).toMatchObject({ delayed: false, delivered_late: false });
    expect(shipment.history.map((h: any) => h.status)).toEqual(["posted", "in_transit", "delivered"]);

    const jobs = await (await send("POST", "/jobs/check-delays")).json();
    expect(jobs.newly_alerted).toBe(0);
  });

  it("envelope de outro envio: a API responde 502 e o envio consultado não é alterado", async () => {
    await send("POST", "/shipments", { tracking_code: "BR779", carrier: "via-rapida" });
    hub.state.trackings.set("BR779", {
      tracking_number: "OTHER",
      courier: "unknown-carrier",
      checkpoints: [{ id: "1", status_code: "40", message: "Entregue", time: "2026-06-01T12:00:00Z", city: null }],
    });
    const res = await send("POST", "/shipments/BR779/refresh");
    expect(res.status).toBe(502);
    expect(await res.json()).toMatchObject({ error: "aggregator_unavailable", kind: "invalid_payload" });

    const shipment = await (await send("GET", "/shipments/BR779")).json();
    expect(shipment).toMatchObject({ status: null, delivered_at: null, history: [] });
  });

  it("se o agregador cai, a API responde 502 em vez de inventar estado", async () => {
    await send("POST", "/shipments", { tracking_code: "BR778", carrier: "via-rapida" });
    hub.state.nextResponse = { status: 503, body: "{}" };
    const res = await send("POST", "/shipments/BR778/refresh");
    hub.state.nextResponse = null;
    expect(res.status).toBe(502);
    expect(await res.json()).toMatchObject({ error: "aggregator_unavailable", kind: "http" });
  });

  it("trocar o agregador não muda nada para quem usa a API: o mesmo fluxo roda com outra implementação da interface", async () => {
    const other = new InMemoryAggregator();
    other.script("BR1", [viaRapida(POSTED, 0), viaRapida(IN_TRANSIT, 2 * H), viaRapida(DELIVERED, 9 * H)]);
    const app = build(other);
    const call = async (method: string, path: string, body?: unknown) =>
      (await app.request(path, { method, headers: { "content-type": "application/json" }, body: body ? JSON.stringify(body) : undefined })).json() as Promise<any>;

    await call("POST", "/shipments", { tracking_code: "BR1", carrier: "via-rapida" });
    expect(await call("POST", "/shipments/BR1/refresh")).toMatchObject({ added: 3, status: "delivered" });
  });
});

test/concurrency.test.ts.source:
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterAll, describe, expect, it } from "vitest";
import { openDatabase } from "../src/db.ts";
import { loadShipment, registerShipment } from "../src/store.ts";
import { setup } from "./helpers.ts";
import { tsWorker } from "./spawn-worker.ts";
import { DELIVERED, H, IN_TRANSIT, OUT_FOR_DELIVERY, POSTED, T0, iso } from "./fixtures.ts";

const dir = mkdtempSync(join(tmpdir(), "rastreio-"));
afterAll(() => rmSync(dir, { recursive: true, force: true }));

describe("concorrência", () => {
  it("4 workers com conexões separadas consultando os mesmos eventos em ordens diferentes: um evento por ocorrência e o mesmo status final", async () => {
    const path = join(dir, "race.db");
    openDatabase(path).close();
    const events = [POSTED, IN_TRANSIT, OUT_FOR_DELIVERY, DELIVERED].map((rawStatus, i) => ({ rawStatus, occurredAt: iso(i * 3 * H) }));
    const run = (worker: number) =>
      new Promise<Array<{ added: number; duplicates: number }>>((resolve, reject) => {
        const w = tsWorker(new URL("./worker.ts", import.meta.url), { path, worker, events });
        w.once("message", resolve);
        w.once("error", reject);
      });
    const outputs = await Promise.all([0, 1, 2, 3].map(run));

    const totalAdded = outputs.flat().reduce((sum, o) => sum + o.added, 0);
    expect(totalAdded).toBe(4); // cada ocorrência entrou exatamente uma vez, de todos os workers somados

    const db = openDatabase(path);
    const view = loadShipment(db, "BR1")!;
    expect(view.history).toHaveLength(4);
    expect(view.status).toBe("delivered");
    expect((db.prepare("SELECT COUNT(*) AS n FROM tracking_events").get() as { n: number }).n).toBe(4);
  }, 30_000);

  it("4 workers verificando atrasos ao mesmo tempo, cada um com a sua conexão: cada aviso é entregue exatamente uma vez", async () => {
    const path = join(dir, "alerts.db");
    const db = openDatabase(path);
    const codes = ["BR1", "BR2", "BR3", "BR4", "BR5", "BR6"];
    for (const code of codes) registerShipment(db, { code, carrier: "via-rapida", creatorId: null, campaignId: null }, () => new Date(T0));
    db.close();

    const run = () =>
      new Promise<{ result: { newly_alerted: number; notified: number }; sent: string[] }>((resolve, reject) => {
        const w = tsWorker(new URL("./alerts-worker.ts", import.meta.url), { path, nowMs: T0 + 100 * H });
        w.once("message", resolve);
        w.once("error", reject);
      });
    const outputs = await Promise.all([run(), run(), run(), run()]);

    const delivered = outputs.flatMap((o) => o.sent).sort();
    expect(delivered).toEqual(codes); // nenhum aviso perdido e nenhum duplicado
    expect(outputs.reduce((sum, o) => sum + o.result.newly_alerted, 0)).toBe(codes.length);
    const verify = openDatabase(path);
    expect(verify.prepare("SELECT COUNT(*) AS n FROM alerts WHERE notified_at IS NOT NULL").get()).toEqual({ n: codes.length });
    expect(verify.prepare("SELECT COUNT(*) AS n FROM alerts").get()).toEqual({ n: codes.length });
  }, 30_000);

  it("várias verificações de atraso no mesmo processo avisam uma vez só", async () => {
    const t = setup({ thresholdHours: 72 });
    await t.register("BR1");
    t.setNow(100 * H);
    const results = await Promise.all(Array.from({ length: 10 }, () => t.checkDelays()));
    expect(t.notifier.sent).toHaveLength(1);
    expect(results.reduce((sum, r) => sum + r.body.newly_alerted, 0)).toBe(1);
  });
});

test/status.test.ts.source:
import fc from "fast-check";
import { describe, expect, it } from "vitest";
import { normalizeEvent } from "../src/domain/normalize.ts";
import { foldEvents } from "../src/domain/status.ts";
import type { NormalizedEvent } from "../src/domain/types.ts";
import { DELIVERED, FAILED_ATTEMPT, H, IN_TRANSIT, OUT_FOR_DELIVERY, POSTED, iso, viaRapida } from "./fixtures.ts";

const ev = (raw: string, offsetMs: number): NormalizedEvent => normalizeEvent("via-rapida", viaRapida(raw, offsetMs));

describe("status atual a partir do histórico", () => {
  it("sem eventos não há status (o pacote só foi cadastrado)", () => {
    expect(foldEvents([])).toMatchObject({ status: null, reason: "no_events_yet", startedAt: null, deliveredAt: null });
  });

  it("vale o evento mais recente por data de ocorrência, não pela ordem de chegada", () => {
    const fold = foldEvents([ev(OUT_FOR_DELIVERY, 3 * H), ev(POSTED, 0), ev(IN_TRANSIT, 1 * H)]);
    expect(fold.status).toBe("out_for_delivery");
    expect(fold.startedAt).toBe(iso(0));
    expect(fold.lastEventAt).toBe(iso(3 * H));
  });

  it("evento antigo que chega depois não faz o status voltar", () => {
    const arrivedFirst = ev(OUT_FOR_DELIVERY, 3 * H);
    const arrivedLater = ev(IN_TRANSIT, 1 * H);
    expect(foldEvents([arrivedFirst]).status).toBe("out_for_delivery");
    expect(foldEvents([arrivedFirst, arrivedLater]).status).toBe("out_for_delivery");
  });

  it("exceção que se resolve: trânsito depois de uma tentativa falha recupera o status", () => {
    const fold = foldEvents([ev(IN_TRANSIT, 0), ev(FAILED_ATTEMPT, 2 * H), ev(OUT_FOR_DELIVERY, 5 * H)]);
    expect(fold.status).toBe("out_for_delivery");
  });

  it("exceção mais recente que o trânsito é o status atual", () => {
    expect(foldEvents([ev(IN_TRANSIT, 0), ev(FAILED_ATTEMPT, 2 * H)]).status).toBe("exception");
  });

  it("entregue é terminal: evento posterior fica no histórico, marcado, e não muda o status", () => {
    const delivered = ev(DELIVERED, 5 * H);
    const late = ev(IN_TRANSIT, 6 * H);
    const fold = foldEvents([delivered, late]);
    expect(fold.status).toBe("delivered");
    expect(fold.deliveredAt).toBe(iso(5 * H));
    expect([...fold.afterDelivered]).toEqual([late.dedupeKey]);
  });

  it("uma segunda confirmação de entrega, mais tarde, não é marcada como posterior à entrega", () => {
    const fold = foldEvents([ev(DELIVERED, 5 * H), ev(DELIVERED, 6 * H)]);
    expect(fold.afterDelivered.size).toBe(0);
    expect(fold.deliveredAt).toBe(iso(5 * H));
  });

  it("evento no mesmo instante da entrega não é marcado como posterior", () => {
    expect(foldEvents([ev(DELIVERED, 5 * H), ev(IN_TRANSIT, 5 * H)]).afterDelivered.size).toBe(0);
  });

  it("evento anterior à entrega não é marcado como posterior", () => {
    const transit = ev(IN_TRANSIT, 1 * H);
    const fold = foldEvents([ev(DELIVERED, 5 * H), transit]);
    expect(fold.afterDelivered.size).toBe(0);
  });

  it("empate de horário: entregue vence exceção, que vence saiu para entrega, trânsito e postado", () => {
    expect(foldEvents([ev(POSTED, 0), ev(IN_TRANSIT, 0)]).status).toBe("in_transit");
    expect(foldEvents([ev(IN_TRANSIT, 0), ev(OUT_FOR_DELIVERY, 0)]).status).toBe("out_for_delivery");
    expect(foldEvents([ev(OUT_FOR_DELIVERY, 0), ev(FAILED_ATTEMPT, 0)]).status).toBe("exception");
    expect(foldEvents([ev(FAILED_ATTEMPT, 0), ev(DELIVERED, 0)]).status).toBe("delivered");
  });

  it("status desconhecido mais recente vira exceção com o motivo do evento que decidiu", () => {
    const unknown = normalizeEvent("via-rapida", viaRapida("INVENTADO", 4 * H));
    const fold = foldEvents([ev(IN_TRANSIT, 0), unknown]);
    expect(fold).toMatchObject({ status: "exception", reason: "unmapped_carrier_status" });
  });

  it("exceções no mesmo instante, uma mapeada (90) e outra inventada: o motivo é o da desconhecida, em qualquer ordem", () => {
    const known = ev(FAILED_ATTEMPT, 4 * H);
    const unknown = normalizeEvent("via-rapida", viaRapida("INVENTADO", 4 * H));
    expect(foldEvents([known, unknown])).toMatchObject({ status: "exception", reason: "unmapped_carrier_status" });
    expect(foldEvents([unknown, known])).toMatchObject({ status: "exception", reason: "unmapped_carrier_status" });
  });

  it("a regra vale pelo motivo, não pela ordem alfabética do código: inventado que ordena antes do conhecido também vence", () => {
    // "000_INVENTADO" ordena antes de "90" na dedupeKey; só a regra do motivo faz o inventado vencer nos dois sentidos
    const known = ev(FAILED_ATTEMPT, 4 * H);
    const unknown = normalizeEvent("via-rapida", viaRapida("000_INVENTADO", 4 * H));
    expect(unknown.dedupeKey < known.dedupeKey).toBe(true);
    expect(foldEvents([known, unknown]).reason).toBe("unmapped_carrier_status");
    expect(foldEvents([unknown, known]).reason).toBe("unmapped_carrier_status");
  });

  it("exceções empatadas com o mesmo motivo também dão sempre o mesmo resultado, qualquer que seja a ordem", () => {
    const a = normalizeEvent("via-rapida", viaRapida("INVENTADO_A", 4 * H));
    const b = normalizeEvent("via-rapida", viaRapida("INVENTADO_B", 4 * H));
    expect(foldEvents([a, b])).toEqual(foldEvents([b, a]));
  });

  it("status desconhecido nunca produz entregue, mesmo sem outros eventos", () => {
    const fold = foldEvents([normalizeEvent("via-rapida", viaRapida("ENTREGUE_MAS_NAO_SEI", 0))]);
    expect(fold.status).toBe("exception");
    expect(fold.deliveredAt).toBeNull();
  });
});

describe("status atual: propriedades", () => {
  const rawArb = fc.constantFrom(POSTED, IN_TRANSIT, OUT_FOR_DELIVERY, DELIVERED, FAILED_ATTEMPT, "INVENTADO");
  const eventsArb = fc
    .array(fc.record({ raw: rawArb, ms: fc.integer({ min: 0, max: 20 }) }), { maxLength: 8 })
    .map((list) => list.map((e) => ev(e.raw, e.ms * H)));

  const orderIndependence = fc.property(eventsArb, fc.nat(), (events, seed) => {
    const shuffled = [...events.slice(seed % (events.length || 1)), ...events.slice(0, seed % (events.length || 1))].reverse();
    const a = foldEvents(events);
    const b = foldEvents(shuffled);
    expect(b.status).toBe(a.status);
    expect(b.reason).toBe(a.reason);
    expect([...b.afterDelivered].sort()).toEqual([...a.afterDelivered].sort());
  });

  it("qualquer ordem de chegada dos mesmos eventos dá o mesmo status, o mesmo motivo e a mesma marcação", () => {
    fc.assert(orderIndependence);
  });

  it("replay do caso que a auditoria reproduziu (seed 559970327): a ordem de chegada não muda status nem motivo", () => {
    fc.assert(orderIndependence, { seed: 559970327, path: "91:9:10:10:18:19:19:19:9:15", numRuns: 1 });
  });

  it("reenviar eventos já recebidos não muda nada", () => {
    fc.assert(
      fc.property(eventsArb, (events) => {
        const unique = new Map(events.map((e) => [e.dedupeKey, e]));
        const once = foldEvents([...unique.values()]);
        const twice = foldEvents([...unique.values(), ...unique.values()]);
        expect(twice.status).toBe(once.status);
      }),
    );
  });

  it("entregue só aparece se houve um evento de entrega mapeado, e depois dele o status não muda", () => {
    fc.assert(
      fc.property(eventsArb, (events) => {
        const fold = foldEvents(events);
        const hasDelivered = events.some((e) => e.status === "delivered");
        expect(fold.status === "delivered").toBe(hasDelivered);
        if (hasDelivered) {
          const deliveredAt = Math.min(...events.filter((e) => e.status === "delivered").map((e) => Date.parse(e.occurredAt)));
          expect(Date.parse(fold.deliveredAt as string)).toBe(deliveredAt);
        }
      }),
    );
  });
});

test/delays.test.ts.source:
import { describe, expect, it } from "vitest";
import { DELIVERED, H, IN_TRANSIT, POSTED, viaRapida } from "./fixtures.ts";
import { setup } from "./helpers.ts";

async function shipmentWith(t: ReturnType<typeof setup>, code: string, events: ReturnType<typeof viaRapida>[]) {
  await t.register(code, "via-rapida", { creator_id: "crt_ana", campaign_id: "cmp_1" });
  t.aggregator.script(code, events);
  await t.refresh(code);
}

describe("aviso de atraso (limite de 72h, relógio controlado)", () => {
  it("no limite exato ainda não é atraso; 1 ms depois é, e o aviso sai", async () => {
    const t = setup({ thresholdHours: 72 });
    await shipmentWith(t, "BR1", [viaRapida(POSTED, 0), viaRapida(IN_TRANSIT, 10 * H)]);

    t.setNow(72 * H);
    expect((await t.get("BR1")).body.delay).toMatchObject({ delayed: false, elapsed_hours: 72, threshold_hours: 72 });
    expect((await t.checkDelays()).body).toMatchObject({ newly_alerted: 0, notified: 0 });

    t.setNow(72 * H + 1);
    expect((await t.get("BR1")).body.delay.delayed).toBe(true);
    expect((await t.checkDelays()).body).toMatchObject({ newly_alerted: 1, notified: 1 });
    expect(t.notifier.sent).toMatchObject([
      { tracking_code: "BR1", kind: "transit_delay", creator_id: "crt_ana", campaign_id: "cmp_1", status: "in_transit", threshold_hours: 72 },
    ]);
  });

  it("entrega normal nunca é marcada como atraso, nem quando a verificação roda semanas depois", async () => {
    const t = setup({ thresholdHours: 72 });
    await shipmentWith(t, "BR1", [viaRapida(POSTED, 0), viaRapida(DELIVERED, 50 * H)]);

    t.setNow(30 * 24 * H);
    expect((await t.get("BR1")).body.delay).toMatchObject({ delayed: false, delivered_late: false });
    expect((await t.checkDelays()).body.newly_alerted).toBe(0);
    expect(t.notifier.sent).toHaveLength(0);
  });

  it("entrega que demorou mais que o limite não gera aviso, só aparece como tardia", async () => {
    const t = setup({ thresholdHours: 72 });
    await shipmentWith(t, "BR1", [viaRapida(POSTED, 0), viaRapida(DELIVERED, 100 * H)]);
    t.setNow(200 * H);
    expect((await t.get("BR1")).body.delay).toMatchObject({ delayed: false, delivered_late: true });
    expect((await t.checkDelays()).body.newly_alerted).toBe(0);
  });

  it("o aviso sai uma vez só, por mais que o job rode", async () => {
    const t = setup({ thresholdHours: 72 });
    await shipmentWith(t, "BR1", [viaRapida(POSTED, 0)]);
    t.setNow(100 * H);
    await t.checkDelays();
    await t.checkDelays();
    t.setNow(200 * H);
    await t.checkDelays();
    expect(t.notifier.sent).toHaveLength(1);
    expect((await t.alerts()).body).toHaveLength(1);
  });

  it("pacote parado em exceção também gera aviso quando passa do limite", async () => {
    const t = setup({ thresholdHours: 72 });
    await shipmentWith(t, "BR1", [viaRapida(POSTED, 0), viaRapida("INVENTADO", 5 * H)]);
    t.setNow(80 * H);
    await t.checkDelays();
    expect(t.notifier.sent[0]).toMatchObject({ tracking_code: "BR1", status: "exception" });
  });

  it("código cadastrado que nunca recebeu evento atrasa a partir do cadastro", async () => {
    const t = setup({ thresholdHours: 72 });
    await t.register("BR1");
    t.setNow(73 * H);
    expect((await t.checkDelays()).body.newly_alerted).toBe(1);
  });

  it("se o destino do aviso falha, o aviso não se perde: sai na próxima verificação", async () => {
    const t = setup({ thresholdHours: 72 });
    await shipmentWith(t, "BR1", [viaRapida(POSTED, 0)]);
    t.setNow(100 * H);
    t.notifier.fail = true;
    expect((await t.checkDelays()).body).toMatchObject({ newly_alerted: 1, notified: 0 });
    expect(t.notifier.sent).toHaveLength(0);

    t.notifier.fail = false;
    expect((await t.checkDelays()).body).toMatchObject({ newly_alerted: 0, notified: 1 });
    expect(t.notifier.sent).toHaveLength(1);
  });

  it("só avisa dos pacotes atrasados, não dos que estão no prazo", async () => {
    const t = setup({ thresholdHours: 72 });
    await shipmentWith(t, "BR_VELHO", [viaRapida(POSTED, 0)]);
    await shipmentWith(t, "BR_NOVO", [viaRapida(POSTED, 90 * H)]);
    t.setNow(100 * H);
    await t.checkDelays();
    expect(t.notifier.sent.map((a) => a.tracking_code)).toEqual(["BR_VELHO"]);
  });
});

test/stale-alerts.test.ts.source:
import { describe, expect, it } from "vitest";
import { checkDelays, listAlerts, type DelayAlert } from "../src/alerts.ts";
import { openDatabase } from "../src/db.ts";
import { ingestEvents, registerShipment } from "../src/store.ts";
import { DELIVERED, H, IN_TRANSIT, POSTED, T0, viaRapida } from "./fixtures.ts";
import { setup } from "./helpers.ts";

/** Avisos que ficaram pendentes (o destino estava fora do ar) e que o mundo mudou antes do reenvio. */
describe("aviso pendente que ficou obsoleto", () => {
  async function pendingAlert() {
    const t = setup({ thresholdHours: 72 });
    await t.register("BR1", "via-rapida", { creator_id: "crt_ana", campaign_id: "cmp_1" });
    t.aggregator.script("BR1", [viaRapida(POSTED, 0)]);
    await t.refresh("BR1");
    t.setNow(100 * H);
    t.notifier.fail = true;
    expect((await t.checkDelays()).body).toMatchObject({ newly_alerted: 1, notified: 0 });
    t.notifier.fail = false;
    return t;
  }

  it("chega a entrega, ocorrida dentro do prazo, fora de ordem: o aviso antigo não é enviado e fica descartado", async () => {
    const t = await pendingAlert();
    t.aggregator.script("BR1", [viaRapida(POSTED, 0), viaRapida(DELIVERED, 50 * H)]);
    await t.refresh("BR1");
    expect((await t.get("BR1")).body.delay).toMatchObject({ delayed: false, delivered_late: false });

    expect((await t.checkDelays()).body).toMatchObject({ newly_alerted: 0, notified: 0, discarded: 1 });
    expect(t.notifier.sent).toHaveLength(0);
    expect((await t.alerts()).body).toMatchObject([{ tracking_code: "BR1", status: "discarded", discard_reason: "delivered", notified: false }]);
  });

  it("um aviso descartado não é reenviado nas execuções seguintes", async () => {
    const t = await pendingAlert();
    t.aggregator.script("BR1", [viaRapida(POSTED, 0), viaRapida(DELIVERED, 50 * H)]);
    await t.refresh("BR1");
    await t.checkDelays();
    t.setNow(500 * H);
    expect((await t.checkDelays()).body).toMatchObject({ newly_alerted: 0, notified: 0, discarded: 0 });
    expect(t.notifier.sent).toHaveLength(0);
  });

  it("se continua atrasado, o aviso sai com o estado atual (não com o de quando foi criado)", async () => {
    const t = await pendingAlert();
    t.aggregator.script("BR1", [viaRapida(POSTED, 0), viaRapida(IN_TRANSIT, 60 * H)]);
    await t.refresh("BR1");
    t.setNow(110 * H);

    expect((await t.checkDelays()).body).toMatchObject({ newly_alerted: 0, notified: 1, discarded: 0 });
    expect(t.notifier.sent).toHaveLength(1);
    expect(t.notifier.sent[0]).toMatchObject({
      tracking_code: "BR1",
      status: "in_transit",
      elapsed_hours: 110,
      detected_at: new Date(T0 + 110 * H).toISOString(),
    });
    expect((await t.alerts()).body[0]).toMatchObject({ status: "notified", notified: true });
  });
});

describe("reavaliação do aviso quando o limite muda", () => {
  const now = (hours: number) => () => new Date(T0 + hours * H);
  function shipmentPostedAtT0() {
    const db = openDatabase(":memory:");
    registerShipment(db, { code: "BR1", carrier: "via-rapida", creatorId: null, campaignId: null }, now(0));
    ingestEvents(db, "BR1", [viaRapida(POSTED, 0)], now(0));
    return db;
  }
  const failing = { notify: async (_alert: DelayAlert) => { throw new Error("fora do ar"); } };
  const collecting = (sent: DelayAlert[]) => ({ notify: async (alert: DelayAlert) => void sent.push(alert) });

  it("com o limite aumentado, o aviso pendente deixa de fazer sentido e é descartado", async () => {
    const db = shipmentPostedAtT0();
    await checkDelays(db, { now: now(100), thresholdHours: 72, notifier: failing });
    const sent: DelayAlert[] = [];
    const result = await checkDelays(db, { now: now(101), thresholdHours: 168, notifier: collecting(sent) });
    expect(result).toMatchObject({ newly_alerted: 0, notified: 0, discarded: 1 });
    expect(sent).toHaveLength(0);
    expect(listAlerts(db)).toMatchObject([{ tracking_code: "BR1", status: "discarded", discard_reason: "within_threshold" }]);
  });

  it("se um envio descartado volta a estar atrasado, o aviso é reativado, sem duplicar", async () => {
    const db = shipmentPostedAtT0();
    await checkDelays(db, { now: now(100), thresholdHours: 72, notifier: failing });
    await checkDelays(db, { now: now(101), thresholdHours: 168, notifier: collecting([]) });

    const sent: DelayAlert[] = [];
    const again = await checkDelays(db, { now: now(200), thresholdHours: 168, notifier: collecting(sent) });
    expect(again).toMatchObject({ newly_alerted: 1, notified: 1 });
    expect(sent).toHaveLength(1);
    expect(db.prepare("SELECT COUNT(*) AS n FROM alerts").get()).toEqual({ n: 1 });
  });
});

test/store.test.ts.source:
import { describe, expect, it } from "vitest";
import { openDatabase } from "../src/db.ts";
import { ingestEvents, loadShipment, normalizeCode, registerShipment } from "../src/store.ts";
import { IN_TRANSIT, POSTED, DELIVERED, H, iso, viaRapida } from "./fixtures.ts";

const now = () => new Date("2026-06-01T00:00:00.000Z");
const shipment = (carrier = "via-rapida") => ({ code: "BR1", carrier, creatorId: null, campaignId: null });

describe("persistência de envios", () => {
  it("cadastrar duas vezes o mesmo código e transportadora é 'exists'; com outra transportadora é 'conflict'", () => {
    const db = openDatabase(":memory:");
    expect(registerShipment(db, shipment(), now)).toBe("created");
    expect(registerShipment(db, shipment(), now)).toBe("exists");
    expect(registerShipment(db, shipment("correio-norte"), now)).toBe("conflict");
  });

  it("ingerir eventos de um envio que não existe devolve null e não grava nada", () => {
    const db = openDatabase(":memory:");
    expect(ingestEvents(db, "NADA", [viaRapida(POSTED, 0)], now)).toBeNull();
    expect((db.prepare("SELECT COUNT(*) AS n FROM tracking_events").get() as { n: number }).n).toBe(0);
  });

  it("normaliza o código: sem espaços nas pontas e em maiúsculas", () => {
    expect(normalizeCode("  ab-1x ")).toBe("AB-1X");
  });

  it("o histórico sai ordenado pela data de ocorrência, não pela ordem em que foi gravado", () => {
    const db = openDatabase(":memory:");
    registerShipment(db, shipment(), now);
    ingestEvents(db, "BR1", [viaRapida(DELIVERED, 9 * H)], now);
    ingestEvents(db, "BR1", [viaRapida(POSTED, 0)], now);
    ingestEvents(db, "BR1", [viaRapida(IN_TRANSIT, 4 * H)], now);
    expect(loadShipment(db, "BR1")!.history.map((h) => h.occurred_at)).toEqual([iso(0), iso(4 * H), iso(9 * H)]);
  });

  it("eventos no mesmo instante saem numa ordem estável", () => {
    const db = openDatabase(":memory:");
    registerShipment(db, shipment(), now);
    ingestEvents(db, "BR1", [viaRapida("21", 0), viaRapida("20", 0)], now);
    expect(loadShipment(db, "BR1")!.history.map((h) => h.raw_status)).toEqual(["20", "21"]);
  });

  it("os campos derivados do envio acompanham o histórico", () => {
    const db = openDatabase(":memory:");
    registerShipment(db, shipment(), now);
    ingestEvents(db, "BR1", [viaRapida(POSTED, 0), viaRapida(DELIVERED, 5 * H)], now);
    expect(db.prepare("SELECT status, started_at, delivered_at FROM shipments").get()).toEqual({
      status: "delivered",
      started_at: iso(0),
      delivered_at: iso(5 * H),
    });
  });
});

